from typing import Annotated, Any
from fastapi import FastAPI, Query
from pydantic import BeforeValidator, WithJsonSchema
import pytest

app = FastAPI()

FilterableStr = Annotated[
    str | dict,
    BeforeValidator(lambda x: x),
    WithJsonSchema({"type": "string"}, mode="serialization"),
]

@app.get("/hello")
async def get_hello(data: FilterableStr | None = Query(default=None)) -> Any:
    return data

def test_invalid_query_param_error_message():
    from fastapi.dependencies.utils import get_dependant
    try:
        get_dependant(path="/hello", call=get_hello)
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
        # This is what we EXPECT after the fix. 
        # Before the fix, e should be empty.
        return e

    pytest.fail("AssertionError was not raised")

if __name__ == "__main__":
    try:
        err = test_invalid_query_param_error_message()
        if err is None:
            print("Test failed: AssertionError was not raised")
        elif str(err) == "":
            print("Test failed: AssertionError was raised but had no message")
        elif str(err) == "Query param 'data' must be of one of the supported types":
            print("Test passed: Correct error message received!")
        else:
            print(f"Test failed: Unexpected error message: {err}")
    except Exception as e:
        print(f"Test failed with exception: {e}")
        raise e
EOF
"}

